<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Version.php';require_once __DIR__.'/../core/DB.php';require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/Http.php';require_once __DIR__.'/../core/CacheStore.php';require_once __DIR__.'/../core/Categories.php';require_once __DIR__.'/../core/Views.php';require_once __DIR__.'/../core/StaticGen.php';require_once __DIR__.'/../adapters/Adapter.php';require_once __DIR__.'/../adapters/Tmdb.php';require_once __DIR__.'/../adapters/HongguoDuanju.php';require_once __DIR__.'/../core/ScrapeLoop.php';use Core\CacheStore;use Core\Config;use Core\DB;use Core\StaticGen;use Core\ScrapeLoop;$loopCfg=Config::get('cron',array());ScrapeLoop::manageFromCron();if(isset($loopCfg['loop_enabled'])&&(int)$loopCfg['loop_enabled']===1){if(!isset($loopCfg['minutely_enabled'])||(int)$loopCfg['minutely_enabled']!==1){exit(0);}}$started=microtime(true);$log=array('action'=>'scrape_minutely','version'=>ML_APP_VERSION,'started_at'=>date('Y-m-d H:i:s'),);$detail=array();$okCount=0;$failCount=0;try{$pdo=DB::pdo();CacheStore::ensureScrapeTables();$cronCfg=Config::get('cron',array());$perRun=isset($cronCfg['scrape_per_minute'])?(int)$cronCfg['scrape_per_minute']:1;$perRun=max(1,min(20,$perRun));$log['per_run']=$perRun;$log['cooldown']=array('images'=>CacheStore::scrapeCooldownCount('images'),'enrich'=>CacheStore::scrapeCooldownCount('enrich'),);$imageSt=$pdo->query("SELECT m.id, m.title FROM media_items m
         WHERE (m.poster IS NULL OR m.poster = '' OR m.backdrop IS NULL OR m.backdrop = '')
           AND m.source IN ('tmdb', 'hongguoduanju', 'pansou', 'manual')
           AND ".CacheStore::scrapeCooldownClause('images')."
         ORDER BY m.id ASC LIMIT ".$perRun);$imageRows=$imageSt->fetchAll(\PDO::FETCH_ASSOC);if(!empty($imageRows)){$log['phase']='images';$log['picked']=count($imageRows);$okIds=array();$lastMsg='';foreach($imageRows as $row){$id=(int)$row['id'];$title=(string)$row['title'];$result=CacheStore::autoScrapeImages('',1,'all',$id,false);$scraped=isset($result['scraped'])?(int)$result['scraped']:0;$log['total']=isset($result['total'])?(int)$result['total']:0;$log['scraped']=$scraped;$log['failed']=isset($result['failed'])?(int)$result['failed']:0;if(!empty($result['busy'])){$log['status']='busy';$log['message']='已有刮削任务运行中';break;}elseif(!empty($result['error'])){$log['status']='error';$log['message']=(string)$result['error'];break;}$err='';if($scraped>0){$okIds[]=$id;$okCount++;$log['item_id']=$id;}else{$failCount++;$err=isset($result['last_error'])?(string)$result['last_error']:'本次未补到图片';$lastMsg=$err;}$detail[]=array('id'=>$id,'ok'=>($scraped>0),'title'=>$title,'error'=>$err);}if(!empty($okIds)){foreach($okIds as $id){try{StaticGen::buildOne((int)$id);$log['static_built']=true;}catch(\Throwable $e){$log['static_built']=false;$log['static_error']=$e->getMessage();}}$log['status']='done';if($lastMsg!==''){$log['message']=$lastMsg;}}elseif(empty($log['status'])){$log['status']='failed';$log['message']=$lastMsg!==''?$lastMsg:'本次未补到图片';}}else{$log['phase']='enrich';$enrichSt=$pdo->query("SELECT m.id, m.title FROM media_items m
             WHERE m.type <> 'person'
               AND (COALESCE(m.overview,'') = ''
