                    OR m.year IS NULL OR m.rating IS NULL OR COALESCE(m.genres,'') = '')
               AND ".CacheStore::scrapeCooldownClause('enrich')."
             ORDER BY m.id ASC LIMIT ".$perRun);$enrichRows=$enrichSt->fetchAll(\PDO::FETCH_ASSOC);if(empty($enrichRows)){$log['status']='empty';$log['message']='缺图和缺资料队列均已完成';}else{$log['picked']=count($enrichRows);$okIds=array();$lastMsg='';foreach($enrichRows as $row){$id=(int)$row['id'];$title=(string)$row['title'];$result=CacheStore::autoEnrichFields('',1,array(),'all',$id);$scraped=isset($result['scraped'])?(int)$result['scraped']:0;$log['total']=isset($result['total'])?(int)$result['total']:0;$log['scraped']=$scraped;$log['failed']=isset($result['failed'])?(int)$result['failed']:0;if(!empty($result['busy'])){$log['status']='busy';$log['message']='已有刮削任务运行中';break;}elseif(!empty($result['error'])){$log['status']='error';$log['message']=(string)$result['error'];break;}$err='';if($scraped>0){$okIds[]=$id;$okCount++;$log['item_id']=$id;}else{$failCount++;$err=isset($result['detail'][0]['error'])?(string)$result['detail'][0]['error']:'本次未补到资料';$lastMsg=$err;}$detail[]=array('id'=>$id,'ok'=>($scraped>0),'title'=>$title,'error'=>$err);}if(!empty($okIds)){foreach($okIds as $id){try{StaticGen::buildOne((int)$id);$log['static_built']=true;}catch(\Throwable $e){$log['static_built']=false;$log['static_error']=$e->getMessage();}}$log['status']='done';if($lastMsg!==''){$log['message']=$lastMsg;}}elseif(empty($log['status'])){$log['status']='failed';$log['message']=$lastMsg!==''?$lastMsg:'本次未补到资料';}}}}catch(\Throwable $e){$log['status']='error';$log['message']=$e->getMessage();error_log('[scrape_minutely] '.$e->getMessage());}$log['elapsed_ms']=(int)round((microtime(true)-$started)*1000);$log['finished_at']=date('Y-m-d H:i:s');if(!empty($detail)){try{CacheStore::saveScrapeLog(array('kind'=>($log['phase']==='enrich'?'enrich':'images'),'type_filter'=>'','scope'=>'all','target_total'=>count($detail),'scraped'=>$okCount,'failed'=>$failCount,'skipped'=>0,'fields'=>'','duration_ms'=>(int)$log['elapsed_ms'],'detail'=>$detail,'started_at'=>(string)$log['started_at'],));}catch(\Throwable $e){error_log('[scrape_minutely] save scrape log failed: '.$e->getMessage());}}try{CacheStore::writeSyncLog('cron:scrape_minutely',array($log),$okCount);}catch(\Throwable $e){error_log('[scrape_minutely] write log failed: '.$e->getMessage());}echo json_encode($log,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\n";